$valores = $params["value"]; // Ex: "Administradores,CGM,COMDEC"

$data = [];

if (is_array($valores)) {
    foreach ($valores as $valor) {

        $valor = trim($valor);
        $safeValor = addslashes($valor);
        $rs = DB::Query("SELECT uid as fuid_group FROM app.t_groups WHERE name = '{$safeValor}' LIMIT 1");

        if ($rs) {
            $row = $rs->fetchAssoc();
            if ($row) {
                $data[] = $row["fuid_group"];
            }
        } else {
            echo "<script>alert('Erro ao consultar grupo: {$valor}')</script>";
        }

				$result["fuid_groups"] = implode(',', $data);
    }

} else {
    $valores = trim($valores);
    $safeValor = addslashes($valores);
    $rs = DB::Query("SELECT uid as fuid_group FROM app.t_groups WHERE name = '{$safeValor}' LIMIT 1");

    if ($rs) {
        $row = $rs->fetchAssoc();
        if ($row) {
            $result["fuid_groups"] = $row["fuid_group"];
        }
    } else {
        echo "<script>alert('Erro ao consultar grupo: {$valores}')</script>";
    }
}
